    /// <summary>The meeting a Pokemon of this species and form came of, in this version; the first meeting with an Ultra Beast is left aside for the ones that come after.</summary>
    public static Met7? Find(ushort species, byte form, GameVersion version, byte level) =>
        All.FirstOrDefault(m => m.Species == species && m.Form == form && m.Level == level && (m.Version == GameVersion.USUM || m.Version == version) && !m.Group.Contains("First Encounter"));
